\ Clapping Music

: dup { t -- t t } t t ;

: getbit { b n -- t }
  1 b << dup
  n & ==
;

: envelope { t -- e }
  t ~ 0x3FFF &
  dup * 14 >>
  dup * 14 >>
;

: noise { t -- n }
  t t t * 4 >> * 4 >> i8 i64
;

: audio { c t -- o }
  t 5 * 3 / -> t
  t 14 >> 144 / c *
  t 14 >> +
  12 % 0x6B7 getbit
  t envelope *
  t c + noise * 14 >>
  i8
;

